# o6_13 – Förderwerbende Personen, Betriebsmindestgröße und Zugangsvoraussetzungen
package oepul.o6_13

# ---------------------------------------------------------------------------
# O6_13-GEN-APPL-01 / -02: zulässige Rechtsformen, Beteiligung von
# Gebietskörperschaften höchstens 25 %
# ---------------------------------------------------------------------------
legal_form_row(code) := row if {
	some row in general.applicant_legal_forms
	row.code == code
}

access_failures contains {
	"rule_id": "O6_13-GEN-APPL-01",
	"message": "Rechtsform der förderwerbenden Person ist nicht förderfähig",
} if {
	lf := object.get(applicant, "legal_form", null)
	lf != null
	not legal_form_row(lf)
}

access_failures contains {
	"rule_id": "O6_13-GEN-APPL-02",
	"message": "Beteiligung von Gebietskörperschaften übersteigt 25 %",
} if {
	row := legal_form_row(applicant.legal_form)
	row.max_public_body_share_percent != null
	object.get(applicant, "public_body_share_percent", 0) > row.max_public_body_share_percent
}

# ---------------------------------------------------------------------------
# O6_13-GEN-APPL-03: Gebietskörperschaften sind nur bei den gelisteten
# Maßnahmen zugelassen; o6_13 ist nicht gelistet.
# ---------------------------------------------------------------------------
public_body_exception_applies(y) if {
	some row in general.public_body_exception_measures
	row.measure_code == measure_code
	year_row_matches({"year_from": coalesce(row.year_from, 0), "year_to": row.year_to}, y)
}

access_failures contains {
	"rule_id": "O6_13-GEN-APPL-03",
	"message": "Gebietskörperschaften und deren Einrichtungen sind in o6_13 keine förderwerbenden Personen",
} if {
	is_true(applicant, "is_public_body")
	not public_body_exception_applies(year)
}

# ---------------------------------------------------------------------------
# O6_13-GEN-APPL-04: aktiver Landwirt, landwirtschaftliche Tätigkeit,
# Bewirtschaftung im eigenen Namen und auf eigene Rechnung, Verfügungsgewalt
# ---------------------------------------------------------------------------
applicant_requirement_keys := [
	"is_active_farmer",
	"has_agricultural_activity",
	"farms_in_own_name_and_account",
	"has_control_over_declared_areas",
]

access_failures contains {
	"rule_id": "O6_13-GEN-APPL-04",
	"message": sprintf("Voraussetzung für förderwerbende Person nicht erfüllt: %s", [key]),
} if {
	some key in applicant_requirement_keys
	is_false(applicant, key)
}

# ---------------------------------------------------------------------------
# O6_13-GEN-SIZE-01 / -02: Betriebsmindestgröße nur im 1. ÖPUL-Teilnahmejahr
# ---------------------------------------------------------------------------
first_oepul_participation_year := object.get(input, ["farm", "oepul", "first_participation_year"], year)

is_first_oepul_year if first_oepul_participation_year == year

protected_cultivation_area_ha := object.get(input, ["land", "protected_cultivation_area_ha"], sum([p.area_ha |
	some p in parcels
	is_protected_structure(p)
]))

# Fläche nach § 25 GSP-AV zuzüglich GA-, K20-, GLÖZ-LE-, Mehrnutzenhecken- und Agroforstflächen
minimum_size_total_area_ha := object.get(input, ["land", "total_area_ha"], 0) + object.get(input, ["land", "minimum_size_additional_area_ha"], 0)

minimum_farm_size_met if protected_cultivation_area_ha >= general.minimum_farm_size_first_year.protected_cultivation_min_ha

minimum_farm_size_met if minimum_size_total_area_ha >= general.minimum_farm_size_first_year.total_area_min_ha

minimum_farm_size_required if is_first_oepul_year

access_failures contains {
	"rule_id": "O6_13-GEN-SIZE-01",
	"message": "Betriebsmindestgröße im ersten ÖPUL-Teilnahmejahr nicht erreicht (0,50 ha geschützter Anbau oder 1,50 ha Fläche)",
} if {
	minimum_farm_size_required
	not minimum_farm_size_met
}

# ---------------------------------------------------------------------------
# O6_13-ACC-01: keine Teilnahme an operationellem Programm mit Abgeltung des
# Organismeneinsatzes (unabhängig von der tatsächlichen Abgeltung am Betrieb)
# ---------------------------------------------------------------------------
access_failures contains {
	"rule_id": "O6_13-ACC-01",
	"message": "Mitglied einer Erzeugerorganisation mit operationellem Programm zum Organismeneinsatz – Teilnahme ausgeschlossen",
} if {
	is_true(state, "member_of_producer_organisation_with_op_covering_organisms")
}

# ---------------------------------------------------------------------------
# O6_13-ACC-02: Mindestteilnahme – zumindest ein Gewächshaus oder Folientunnel
# je Teilnahmejahr nach den Vorgaben der Maßnahme bewirtschaftet
# ---------------------------------------------------------------------------
compliant_structures contains p.parcel_id if {
	some p in nue_parcels
	is_protected_structure(p)
	parcel_has_creditable_use(p)
}

minimum_participation_met if count(compliant_structures) >= 1

access_failures contains {
	"rule_id": "O6_13-ACC-02",
	"message": "Kein Gewächshaus oder Folientunnel nach den Vorgaben der Maßnahme bewirtschaftet (Mindestteilnahme)",
} if {
	count(nue_parcels) > 0
	not minimum_participation_met
}

# ---------------------------------------------------------------------------
# O6_13-GEN-LOC-01: geförderte Flächen müssen in Österreich liegen
# (flächenbezogen in parcels.rego geprüft)
# ---------------------------------------------------------------------------
access_requirements_met if count(access_failures) == 0

# o6_13 – Beantragung, Vertragszeitraum, Verlängerung, Erlöschen und Ausstieg
package oepul.o6_13

# ---------------------------------------------------------------------------
# O6_13-CON-01: einjährige Maßnahme (Vertragszeitraum = Kalenderjahr)
# ---------------------------------------------------------------------------
is_one_year_measure if {
	some row in general.one_year_measures
	row.measure_code == measure_code
}

contract_period := {
	"start": iso_date(year, "01-01"),
	"end": iso_date(year, "12-31"),
	"calendar_years": params.contract_period_calendar_years,
} if {
	is_one_year_measure
}

# ---------------------------------------------------------------------------
# O6_13-APP-01: Maßnahmenantrag bis spätestens 31.12. vor Vertragsbeginn
# O6_13-APP-02: letzter Einstieg Förderjahr 2027 (Antrag bis 31.12.2026)
# ---------------------------------------------------------------------------
entry_year := object.get(state, "entry_year", null)

application_date := object.get(state, "measure_application_date", null)

application_deadline(entry) := iso_date(entry - 1, params.application_deadline_month_day)

entry_application_timely if {
	is_string(application_date)
	application_date <= application_deadline(entry_year)
}

entry_year_allowed if entry_year <= params.last_entry_year

new_entry_valid if {
	entry_year == year
	entry_application_timely
	entry_year_allowed
}

contract_failures contains {
	"rule_id": "O6_13-APP-01",
	"message": sprintf("Maßnahmenantrag nicht bis %v gestellt", [application_deadline(entry_year)]),
} if {
	entry_year == year
	not entry_application_timely
}

contract_failures contains {
	"rule_id": "O6_13-APP-02",
	"message": sprintf("Einstieg %v nach dem letzten Einstiegsjahr %v nicht möglich", [entry_year, params.last_entry_year]),
} if {
	entry_year == year
	not entry_year_allowed
}

# ---------------------------------------------------------------------------
# O6_13-CON-02: automatische Verlängerung um ein Förderjahr, wenn nicht
#   abgemeldet; Weiterführung durch Mehrfachantrag mit förderrelevanten Flächen
# O6_13-CON-03: kein Nützlingseinsatz (kein Code NUE) in einem Förderjahr ->
#   Vertrag erlischt
# O6_13-APP-07: nach Erlöschen, Ausstieg, Ausschluss oder Nichtabgabe des MFA
#   ist ein neuer Maßnahmenantrag nötig
# ---------------------------------------------------------------------------
renewal_valid if {
	is_number(entry_year)
	entry_year < year
	is_true(state, "contract_active_previous_year")
	is_true(state, "nue_used_previous_year")
	not is_true(state, "withdrawn_previous_year")
	not is_true(state, "excluded_from_measure")
	not is_false(state, "mfa_submitted_previous_year")
}

contract_failures contains {
	"rule_id": "O6_13-CON-03",
	"message": "Vertrag im Vorjahr erloschen (kein Code NUE / kein Nützlingseinsatz) – neuer Maßnahmenantrag erforderlich",
} if {
	is_number(entry_year)
	entry_year < year
	is_false(state, "nue_used_previous_year")
}

contract_failures contains {
	"rule_id": "O6_13-APP-07",
	"message": "Nach Ausstieg, Ausschluss oder Nichtabgabe des Mehrfachantrages ist ein neuerlicher Maßnahmenantrag erforderlich",
} if {
	is_number(entry_year)
	entry_year < year
	some key in ["withdrawn_previous_year", "excluded_from_measure"]
	is_true(state, key)
}

contract_failures contains {
	"rule_id": "O6_13-APP-07",
	"message": "Mehrfachantrag im Vorjahr nicht abgegeben – neuerlicher Maßnahmenantrag erforderlich",
} if {
	is_number(entry_year)
	entry_year < year
	is_false(state, "mfa_submitted_previous_year")
}

contract_failures contains {
	"rule_id": "O6_13-CON-02",
	"message": "Kein laufender Vertrag aus dem Vorjahr vorhanden",
} if {
	is_number(entry_year)
	entry_year < year
	is_false(state, "contract_active_previous_year")
}

contract_failures contains {
	"rule_id": "O6_13-APP-01",
	"message": "Kein Maßnahmenantrag bzw. Einstiegsjahr angegeben",
} if {
	not is_number(entry_year)
}

contract_basis_valid if new_entry_valid

contract_basis_valid if renewal_valid

# Vertrag erlischt nach dem laufenden Jahr, wenn kein NUE-Schlag beantragt ist
contract_lapses_after_year if count(nue_parcels) == 0

new_application_deadline_for_next_year := application_deadline(year + 1)

# ---------------------------------------------------------------------------
# Ausstieg / Abmeldung
# O6_13-EXIT-01: Ausstieg nach Erfüllung des einjährigen Vertragszeitraumes
# O6_13-EXIT-02: Bekanntgabe online im Rahmen des aktuellen Mehrfachantrages
# O6_13-EXIT-03: Abmeldung 1.1.–31.12. -> Maßnahme im betroffenen Jahr nicht
#   gültig; bei Erfüllung bis 31.12. Abmeldung erst ab 1.1. des Folgejahres
# O6_13-EXIT-04: bis zum Ausstieg sind die Förderverpflichtungen einzuhalten
# O6_13-EXIT-05: Ausstieg bis zur Durchführung/Ankündigung einer VOK oder bis
#   zur Mitteilung des Ergebnisses einer Verwaltungskontrolle
# ---------------------------------------------------------------------------
withdrawal := object.get(state, "withdrawal", {})

withdrawal_date := object.get(withdrawal, "declared_date", null)

withdrawal_declared_in_year if date_in_year(withdrawal_date, year)

withdrawal_blocked_by(key) if {
	cutoff := object.get(state, key, null)
	is_string(cutoff)
	cutoff <= withdrawal_date
}

withdrawal_admissible if {
	withdrawal_declared_in_year
	not withdrawal_blocked_by("on_site_check_announced_date")
	not withdrawal_blocked_by("admin_check_result_notified_date")
}

withdrawal_effective_in_year if {
	withdrawal_admissible
	not is_false(withdrawal, "declared_online_in_mfa")
}

contract_failures contains {
	"rule_id": "O6_13-EXIT-03",
	"message": "Abmeldung im laufenden Förderjahr: Maßnahme im betroffenen Förderjahr nicht mehr gültig",
} if {
	withdrawal_effective_in_year
}

withdrawal_findings contains {
	"rule_id": "O6_13-EXIT-05",
	"message": "Ausstieg nach Ankündigung/Durchführung einer Vor-Ort-Kontrolle bzw. Mitteilung einer Verwaltungskontrolle unzulässig – Verpflichtungen und Kontrollergebnis bleiben maßgeblich",
} if {
	withdrawal_declared_in_year
	not withdrawal_admissible
}

withdrawal_findings contains {
	"rule_id": "O6_13-EXIT-02",
	"message": "Ausstieg ist online auf www.eama.at im Rahmen des aktuellen Mehrfachantrages bekannt zu geben",
} if {
	withdrawal_declared_in_year
	is_false(withdrawal, "declared_online_in_mfa")
}

# Frühestmögliche Abmeldung ohne Verlust der Prämie des laufenden Jahres
earliest_withdrawal_without_loss := iso_date(year + 1, "01-01")

# Ausstieg nach Erfüllung des einjährigen Vertragszeitraumes ist jederzeit (ab
# dem Folgejahr) ohne Rückforderung möglich, da es sich um eine einjährige Maßnahme handelt
exit_possible_after_contract_year if is_one_year_measure

contract_in_force if {
	contract_basis_valid
	not withdrawal_effective_in_year
	access_requirements_met
}

# ---------------------------------------------------------------------------
# O6_13-SANC-05: bei einjährigen Maßnahmen kommt bei Nichterfüllung von
# Förder- bzw. Zugangsvoraussetzungen kein Vertrag zustande
# ---------------------------------------------------------------------------
no_contract_due_to_access_failure if {
	is_one_year_measure
	not access_requirements_met
}

# ---------------------------------------------------------------------------
# O6_13-CONV-01: o6_13 ist nicht in der Liste der umwandelbaren Maßnahmen
# ---------------------------------------------------------------------------
conversion_targets(from) := [t |
	some row in general.measure_conversions
	row.from == from
	some t in row.to
]

conversion_available if count(conversion_targets(measure_code)) > 0

# ---------------------------------------------------------------------------
# O6_13-TRANS-01: Maßnahmenübernahme durch einen anderen, bisher nicht
# teilnehmenden Betrieb bis 15.04. (2023 und 2028: 17.04.); Ausweitung
# höchstens 50 %; Antrag im MFA, Genehmigung durch AMA
# ---------------------------------------------------------------------------
takeover_deadline(y) := iso_date(y, md) if {
	md := general.takeover_deadline_month_day_special_years[sprintf("%d", [y])]
} else := iso_date(y, general.takeover_deadline_month_day)

takeover_only_in_individual_cases if {
	some row in general.takeover_individual_case_only_measures
	row.measure_code == measure_code
}

takeover := object.get(state, "takeover", {})

takeover_findings contains {
	"rule_id": "O6_13-TRANS-01",
	"message": sprintf("Maßnahmenübernahme nach der Frist %v", [takeover_deadline(year)]),
} if {
	d := object.get(takeover, "request_date", null)
	is_string(d)
	d > takeover_deadline(year)
}

takeover_findings contains {
	"rule_id": "O6_13-TRANS-01",
	"message": "Übernehmender Betrieb hat bereits an der Maßnahme teilgenommen",
} if {
	is_true(takeover, "taker_already_participating")
}

takeover_findings contains {
	"rule_id": "O6_13-TRANS-01",
	"message": "Maßnahmenübernahme führt zu einer Ausweitung auf andere Flächen um mehr als 50 %",
} if {
	taken := object.get(takeover, "taken_over_area_ha", 0)
	taken > 0
	object.get(takeover, "extension_to_other_areas_ha", 0) > (taken * general.takeover_max_extension_percent) / 100
}

takeover_findings contains {
	"rule_id": "O6_13-TRANS-01",
	"message": "Maßnahmenübernahme erfordert Genehmigung durch die AMA",
} if {
	is_string(object.get(takeover, "request_date", null))
	is_false(takeover, "approved_by_ama")
}

# o6_13 – Förderverpflichtungen Nützlingseinsatz und Aufzeichnungen
package oepul.o6_13

applications_of(p) := object.get(p, "beneficial_organism_applications", [])

non_creditable_use_codes := {row.code | some row in params.non_creditable_organism_uses}

# ---------------------------------------------------------------------------
# O6_13-OBL-01: Einsatz von Organismen gemäß Aufwandsmengen im
#   AGES-Pflanzenschutzmittelregister
# O6_13-OBL-02: anrechenbar nur Anwendungen, die einen PSM-Einsatz ersetzen
# O6_13-OBL-03: Hummelvölker zur Bestäubung sind nicht anrechenbar
# ---------------------------------------------------------------------------
creditable_application(a) if {
	date_in_year(a.date, year)
	a.listed_in_psm_register == true
	a.applied_at_register_rate == true
	a.replaces_psm_use == true
	not object.get(a, "use_type", "plant_protection") in non_creditable_use_codes
}

creditability_checks := [
	["listed_in_psm_register", "O6_13-OBL-01: Organismus nicht im Pflanzenschutzmittelregister geführt"],
	["applied_at_register_rate", "O6_13-OBL-01: Aufwandsmenge nicht gemäß Pflanzenschutzmittelregister"],
	["replaces_psm_use", "O6_13-OBL-02: Anwendung ersetzt keinen Pflanzenschutzmitteleinsatz"],
]

non_creditable_reasons(a) := (flag_reasons(a) | pollination_reasons(a)) | period_reasons(a)

flag_reasons(a) := {check[1] |
	some check in creditability_checks
	object.get(a, check[0], false) != true
}

pollination_reasons(a) := {"O6_13-OBL-03: Hummelvölker für die Bestäubung sind nicht anrechenbar" |
	object.get(a, "use_type", "plant_protection") in non_creditable_use_codes
}

period_reasons(a) := {"Einsatz nicht im Förderjahr" |
	not date_in_year(object.get(a, "date", null), year)
}

parcel_has_creditable_use(p) if {
	some a in applications_of(p)
	creditable_application(a)
}

parcel_has_full_coverage_use(p) if {
	some a in applications_of(p)
	creditable_application(a)
	a.covers_entire_area == true
}

non_creditable_applications contains {
	"parcel_id": p.parcel_id,
	"date": object.get(a, "date", null),
	"organism_species": object.get(a, "organism_species", null),
	"reasons": non_creditable_reasons(a),
} if {
	some p in nue_parcels
	some a in applications_of(p)
	not creditable_application(a)
}

# Maßnahmenebene: zumindest ein Gewächshaus/Folientunnel mit anrechenbarem Einsatz
beneficial_use_obligation_met if {
	some p in nue_parcels
	is_protected_structure(p)
	parcel_has_creditable_use(p)
}

obligation_violations contains {
	"rule_id": "O6_13-OBL-01",
	"message": "Kein anrechenbarer Nützlingseinsatz gemäß Pflanzenschutzmittelregister in zumindest einem Gewächshaus oder Folientunnel",
} if {
	count(nue_parcels) > 0
	not beneficial_use_obligation_met
}

# ---------------------------------------------------------------------------
# O6_13-DOC-01: schlagbezogene Aufzeichnungen über Art und Menge, Belege über
#   Zukauf, Grund und Ziel sowie Datum des Einsatzes
# O6_13-DOC-02: Vorlage oder andere Aufzeichnungen mit den notwendigen Angaben
# ---------------------------------------------------------------------------
record_field_present(a, "purchase_receipt_available") if a.purchase_receipt_available == true

record_field_present(a, key) if {
	key != "purchase_receipt_available"
	v := object.get(a, key, null)
	v != null
	v != ""
}

missing_record_fields(a) := {row.key |
	some row in params.record_required_fields
	not record_field_present(a, row.key)
}

obligation_violations contains {
	"rule_id": "O6_13-DOC-01",
	"message": sprintf("Aufzeichnung unvollständig auf Schlag %v (%v): fehlend %v", [p.parcel_id, object.get(a, "date", "ohne Datum"), sort(missing)]),
} if {
	some p in nue_parcels
	some a in applications_of(p)
	date_in_year(object.get(a, "date", ""), year)
	missing := missing_record_fields(a)
	count(missing) > 0
}

obligation_violations contains {
	"rule_id": "O6_13-DOC-01",
	"message": sprintf("Aufzeichnungen nicht schlagbezogen geführt (Schlag %v)", [p.parcel_id]),
} if {
	some p in nue_parcels
	is_false(object.get(p, "records", {}), "kept_per_parcel")
}

records_complete if {
	not any_doc_violation
}

any_doc_violation if {
	some v in obligation_violations
	v.rule_id == "O6_13-DOC-01"
}

# o6_13 – teilnahmefähige Flächen, Codierung, Nutzungsart und Förderfähigkeit je Schlag
package oepul.o6_13

# ---------------------------------------------------------------------------
# O6_13-APP-03: Schlag muss in der Feldstücksliste mit Code NUE gekennzeichnet sein
# ---------------------------------------------------------------------------
parcel_codes(p) := object.get(p, "oepul_codes", [])

nue_coded(p) if params.parcel_code in parcel_codes(p)

nue_parcels contains p if {
	some p in parcels
	nue_coded(p)
}

pc(p) := object.get(p, "protected_cultivation", {})

# ---------------------------------------------------------------------------
# O6_13-ELIG-01: befestigte Gewächshäuser mit Folien-, Glas- oder
# Kunststoffeindeckung sowie unbefestigte Folientunnel
# ---------------------------------------------------------------------------
eligible_structure_codes := {row.code | some row in params.eligible_structure_types}

is_protected_structure(p) if {
	s := pc(p)
	s.structure_type == "unfixed_foil_tunnel"
}

is_protected_structure(p) if {
	s := pc(p)
	s.structure_type == "fixed_greenhouse"
	s.covering_material in params.fixed_greenhouse_coverings
}

# ---------------------------------------------------------------------------
# O6_13-APP-05 / O6_13-APP-06: gewachsener Boden -> "A", Töpfe/Substrat -> "GA";
# bei wechselweiser Bewirtschaftung ist der Stand am 1. April maßgeblich
# ---------------------------------------------------------------------------
effective_growing_system(p) := gs if {
	s := pc(p)
	s.growing_system != "alternating"
	gs := s.growing_system
}

effective_growing_system(p) := gs if {
	s := pc(p)
	s.growing_system == "alternating"
	gs := s.growing_system_on_april_1
}

expected_field_use_type(p) := params.field_use_type_by_growing_system[effective_growing_system(p)]

declared_field_use_type(p) := object.get(pc(p), "field_use_type", null)

# ---------------------------------------------------------------------------
# O6_13-ELIG-02..04: Verkaufs-, Schau-, Lagerflächen, ungenutzte Zwischenflächen
# und Gangflächen über das nötige Ausmaß sind nicht förderfähig
# ---------------------------------------------------------------------------
non_eligible_part_ha(p) := sum([object.get(pc(p), row.key, 0) | some row in params.non_eligible_area_components])

eligible_area_ha(p) := max([0, p.area_ha - non_eligible_part_ha(p)])

# ---------------------------------------------------------------------------
# Schlagbezogene Ausschlussgründe (nur für NUE-codierte Schläge relevant)
# ---------------------------------------------------------------------------
parcel_issue(p, rule_id, message) := {
	"parcel_id": p.parcel_id,
	"rule_id": rule_id,
	"message": message,
}

parcel_issues contains parcel_issue(p, "O6_13-ELIG-01", "Schlag liegt nicht in einem befestigten Gewächshaus (Glas/Folie/Kunststoff) oder unbefestigten Folientunnel") if {
	some p in nue_parcels
	not is_protected_structure(p)
}

parcel_issues contains parcel_issue(p, "O6_13-APP-04", "Feldstücksnutzungsart ist weder Ackerland (A) noch Geschützter Anbau (GA)") if {
	some p in nue_parcels
	not declared_field_use_type(p) in params.eligible_field_use_types
}

parcel_issues contains parcel_issue(p, "O6_13-APP-05", sprintf("Nutzungsart %v passt nicht zum Anbausystem (erwartet %v)", [declared_field_use_type(p), expected_field_use_type(p)])) if {
	some p in nue_parcels
	pc(p).growing_system != "alternating"
	declared_field_use_type(p) != expected_field_use_type(p)
}

parcel_issues contains parcel_issue(p, "O6_13-APP-06", sprintf("Wechselweise Bewirtschaftung: Nutzungsart gemäß Stand 1. April muss %v sein", [expected_field_use_type(p)])) if {
	some p in nue_parcels
